CREATE TABLE IF NOT EXISTS posting_jobs (source TEXT NOT NULL, account_id TEXT NOT NULL, external_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','inflight','posted','needs_review','failed')), action TEXT, rule_id TEXT, rule_version INTEGER, qbo_entity_type TEXT, qbo_entity_id TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(source,account_id,external_id));
CREATE TABLE IF NOT EXISTS posting_audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, account_id TEXT NOT NULL, external_id TEXT NOT NULL, action TEXT, status TEXT NOT NULL, detail_category TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);